'use strict';
let checklistRefreshTimer=null;
function checklistRow(item){const li=document.createElement('li');li.className=item.done?'done':'';li.textContent=(item.done?'✓ ':'○ ')+item.text.replace(' — in progress','');return li}
async function refreshWorkChecklist(){try{const r=await fetch('checklist.json',{cache:'no-store'});if(!r.ok)throw Error('Checklist unavailable.');const items=await r.json(),container=$('checklistItems');container.replaceChildren();const groups=[['Director mode',i=>/^(Local AI|Director mode) ·/.test(i.text),true],['Current update delivery',i=>i.text.startsWith('Current delivery · '),true],['Current animation and timeline work',i=>i.text.startsWith('Current animation '),true],['Narration fixes',i=>i.text.startsWith('Narration fixes '),true],['Voice, explainer and scene work',i=>/^(Voice update|Explainer|Scene editing|Walking) ·/.test(i.text),true],['Usability improvements',i=>i.text.startsWith('Usability '),true],['Current batch',i=>/^(Animation ease|Text ·|Text upgrade)/.test(i.text),true],['Selected improvements',i=>/^(Next|Verify actual|Export MP4)/.test(i.text),true],['Installer delivery',i=>i.text.startsWith('Delivery · '),true],['Previous milestones and future ideas',i=>!/^(Local AI ·|Director mode ·|Current delivery ·|Current animation |Narration fixes |Voice update ·|Explainer ·|Scene editing ·|Walking ·|Usability |Animation ease|Text ·|Text upgrade|Next|Verify actual|Export MP4|Delivery · )/.test(i.text),false]];for(const [name,filter,open]of groups){const list=items.filter(filter);if(!list.length)continue;const section=document.createElement('details');section.open=open&&!list.every(i=>i.done);const title=document.createElement('summary');title.textContent=name+' · '+list.filter(i=>i.done).length+' / '+list.length;const ul=document.createElement('ul');for(const item of list)ul.append(checklistRow(item));section.append(title,ul);container.append(section)}}catch{$('checklistItems').textContent='Open CHECKLIST.md in the project folder for the current plan.'}}
$('workChecklist').onclick=async()=>{await refreshWorkChecklist();$('checklist').showModal();clearInterval(checklistRefreshTimer);checklistRefreshTimer=setInterval(()=>{if($('checklist').open)refreshWorkChecklist()},5000)};$('checklist').addEventListener('close',()=>clearInterval(checklistRefreshTimer));
